import { Directory, File, Paths } from 'expo-file-system';
import { createIdGenerator } from '../system/ids';
import type { ImageStore } from '../types';
import { isUriSource, resolveImageId, type ImageStoreDeps } from './imageStoreShared';

export type { ImageStore } from '../types';
export type { ImageStoreDeps } from './imageStoreShared';

const DIR_NAME = 'fashionable-images';
/** Ids are generated by us but may be supplied by callers: never let one escape the directory. */
const SAFE_ID = /^[A-Za-z0-9_-]+$/;

export function createImageStore(deps: ImageStoreDeps = {}): ImageStore {
  const ids = deps.ids ?? createIdGenerator();
  const dir = new Directory(Paths.document, DIR_NAME);

  const fileFor = (id: string): File => {
    if (!SAFE_ID.test(id)) throw new Error(`Invalid image id: ${id}`);
    return new File(dir, `${id}.img`);
  };

  return {
    async save(source, opts) {
      const id = resolveImageId(ids, opts?.id);
      const target = fileFor(id);
      dir.create({ idempotent: true, intermediates: true });
      if (isUriSource(source)) {
        await new File(source.uri).copy(target, { overwrite: true });
      } else {
        target.create({ overwrite: true });
        await target.write(new Uint8Array(await source.arrayBuffer()));
      }
      return id;
    },
    async uri(id) {
      const file = fileFor(id);
      if (!file.exists) throw new Error(`Unknown image id: ${id}`);
      return file.uri;
    },
    async remove(id) {
      const file = fileFor(id);
      if (file.exists) file.delete();
    },
  };
}
